test("production: APP_CACHE__TTL_SECONDS overrides the file", () => {
  const cfg = loadConfig({ env: { APP_ENV: "production", APP_CACHE__TTL_SECONDS: "120" }, file: { cache: { ttlSeconds: 600 } } });
  assert.equal(cfg.cache.ttlSeconds, 120);
  assert.equal(cfg.cache.enabled, true);
});

test("nested env vars override the file in every profile", () => {
  const cfg = loadConfig({
    env: { APP_DB__REPLICA__READ_TIMEOUT_MS: "900", APP_CACHE__REDIS__MAX_RETRIES: "5" },
    file: { db: { replica: { host: "r.internal", readTimeoutMs: 1500 } }, cache: { redis: { maxRetries: 2 } } },
  });
  assert.equal(cfg.db.replica.readTimeoutMs, 900);
  assert.equal(cfg.db.replica.host, "r.internal");
  assert.equal(cfg.cache.redis.maxRetries, 5);
});

test("production: APP_LOG_LEVEL is still ignored (SEC-207)", () => {
